class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

def search_with_wildcard(node, word, index):
    if index == len(word):
        return node.is_end

    char = word[index]
    if char == '.':
        for child in node.children.values():
            if search_with_wildcard(child, word, index + 1):
                return True
        return False
    else:
        if char not in node.children:
            return False
        return search_with_wildcard(node.children[char], word, index + 1)

def autocomplete(node, prefix):
    results = []

    def dfs(current, path):
        if current.is_end:
            results.append(path)
        for char, child in current.children.items():
            dfs(child, path + char)

    dfs(node, prefix)
    return results
